const item = $input.first();

// Binary key names as n8n assigns them from the Form Trigger
const jdBinary      = item.binary['JobDescription'];
const compassBinary = item.binary['CareerCompass'];

if (!jdBinary)      throw new Error('Binary field "JobDescription" not found.');
if (!compassBinary) throw new Error('Binary field "CareerCompass" not found.');

// Single item — both binaries travel together downstream
return [
  {
    json: item.json,
    binary: {
      JobDescription: jdBinary,
      CareerCompass:  compassBinary
    }
  }
];

// Parse Career Compass JSON — filesystem binary mode compatible
const item = $input.first();

if (!item.binary?.CareerCompass) throw new Error('Binary field "CareerCompass" not found.');

// Use helpers.getBinaryDataBuffer() — required in filesystem binaryDataMode
const buffer = await this.helpers.getBinaryDataBuffer(0, 'CareerCompass');
const jsonString = buffer.toString('utf-8');

let parsed;
try {
  parsed = JSON.parse(jsonString);
} catch (e) {
  throw new Error('Failed to parse Career Compass JSON: ' + e.message);
}

// Pass binary through so Extract JD Text can still access JobDescription
return [{ json: { ...item.json, career_compass: parsed }, binary: item.binary }];

// Combine JD text and Career Compass data into single item
const jd_text = $('Extract JD Text').first().json.text || '';
const compassData = $('Parse Career Compass').first().json.career_compass;

const candidate_portrait = compassData?.candidate_portrait;
const profile_matches    = compassData?.profile_matches;

// Validation
const warnings = [];
if (!jd_text)           warnings.push('jd_text is empty — check PDF extraction');
if (!candidate_portrait) warnings.push('candidate_portrait is missing from Career Compass JSON');
if (!profile_matches)    warnings.push('profile_matches is missing from Career Compass JSON');

return [{
  json: {
    jd_text,
    candidate_portrait: typeof candidate_portrait === 'string'
      ? candidate_portrait
      : JSON.stringify(candidate_portrait, null, 2),
    profile_matches: typeof profile_matches === 'string'
      ? profile_matches
      : JSON.stringify(profile_matches, null, 2),
    _warnings: warnings.length > 0 ? warnings : null
  }
}];

// Prepare inputs for Job Fit Analysis
// Combines JD structured data with candidate portrait and profile matches

const jd_structured = $input.first().json.message.content;
const jd_text = $('Combine WF3 Inputs').first().json.jd_text;
const candidate_portrait = $('Combine WF3 Inputs').first().json.candidate_portrait;
const profile_matches = $('Combine WF3 Inputs').first().json.profile_matches;

return [{
  json: {
    jd_structured: typeof jd_structured === 'string'
      ? jd_structured
      : JSON.stringify(jd_structured, null, 2),
    jd_text,
    candidate_portrait,
    profile_matches
  }
}];

