const items = $input.all();
const prepare = $('Prepare Application Inputs').first().json;

return items.map(item => ({
  json: {
    ...item.json,
    fit_analysis: prepare.fit_analysis,
    jd_structured: prepare.jd_structured,
    candidate_portrait: prepare.candidate_portrait
  }
}));

// ── INPUT ──────────────────────────────────────────────────────────────────
// items[0] = LLM — Cover Letter output
// items[1] = LLM — Interview Questions output
// fit_analysis, jd_structured, candidate_portrait injected by Inject Prepare Data
const items = $input.all();

// ── HELPERS ────────────────────────────────────────────────────────────────
const safe = (val) => (val || '').toString()
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const safeParse = (val) => {
  if (!val) return {};
  if (typeof val === 'object') return val;
  try { return JSON.parse(val); } catch(e) { return {}; }
};

const parseContent = (item) => safeParse(item?.json?.message?.content);
const safeList = (arr) => (arr || []).map(i => `<li>${safe(i)}</li>`).join('');

// ── DATA ───────────────────────────────────────────────────────────────────
const coverData     = parseContent(items[0]);
const interviewData = parseContent(items[1]);

const carrier  = items[0]?.json || {};
const fitData  = safeParse(carrier.fit_analysis);
const portrait = safeParse(carrier.candidate_portrait);
const jd       = safeParse(carrier.jd_structured);

// ── FIT SCORE ──────────────────────────────────────────────────────────────
const overall     = fitData?.fit_scores?.overall || 0;
const scoreColour = overall >= 80 ? '#16a34a' : overall >= 60 ? '#d97706' : '#dc2626';

// ── DIMENSION CARDS ────────────────────────────────────────────────────────
const dimCard = (d) => `
  <div class="dim-card">
    <div class="dim-header">
      <span class="dim-name">${safe(d.dimension?.replace(/_/g,' '))}</span>
      <span class="dim-score" style="background:${scoreColour}">${d.score}/25</span>
    </div>
    <div class="dim-row"><span class="dim-label">Role requires</span><span class="dim-text">${safe(d.what_role_requires)}</span></div>
    <div class="dim-row"><span class="dim-label">You bring</span><span class="dim-text">${safe(d.what_candidate_brings)}</span></div>
    ${d.notes ? `<div class="dim-row"><span class="dim-label">Note</span><span class="dim-text">${safe(d.notes)}</span></div>` : ''}
  </div>`;

// ── GAP CARDS ──────────────────────────────────────────────────────────────
const gapCards = (fitData?.gap_analysis || []).map(g => `
  <div class="gap-card">
    <div class="gap-title">${safe(g.gap)}</div>
    <div class="gap-severity sev-${(g.severity||'minor').toLowerCase()}">${safe(g.severity)}</div>
    <div class="gap-section"><span class="gap-label">How to talk about it</span><p>${safe(g.how_to_talk_about_it)}</p></div>
  </div>`).join('');

// ── MISMATCH FLAGS ─────────────────────────────────────────────────────────
const flagCards = (fitData?.mismatch_flags || []).map(f => `
  <div class="flag-card">
    <div class="flag-text">${safe(f.flag)}</div>
    <div class="flag-rec">${safe(f.recommendation?.replace(/_/g,' '))}</div>
  </div>`).join('');

// ── CLIFTON DEPLOYMENT ─────────────────────────────────────────────────────
const cliftonCards = (fitData?.clifton_deployment || []).map(c => `
  <div class="clifton-card">
    <span class="clifton-name">${safe(c.strength)}</span>
    <span class="clifton-text">${safe(c.deploy_for_this_role)}</span>
  </div>`).join('');

// ── COVER LETTER ───────────────────────────────────────────────────────────
const cl = coverData?.cover_letter || {};
const coverHTML = `
  <div class="cover-meta">
    <span class="cover-wc">${cl.word_count || ''} words</span>
  </div>
  <div class="cover-letter-box">
    <p class="cover-salutation">${safe(cl.salutation)},</p>
    <p>${safe(cl.hook)}</p>
    <p>${safe(cl.evidence)}</p>
    <p>${safe(cl.transition_narrative)}</p>
    <p>${safe(cl.close)}</p>
  </div>
  <div class="copy-section">
    <h3>Copy cover letter</h3>
    <p>Click inside the box, select all, copy.</p>
    <textarea onclick="this.select()" readonly>${safe(cl.full_text)}</textarea>
  </div>`;

// ── INTERVIEW QUESTIONS ────────────────────────────────────────────────────
const questions = interviewData?.interview_questions || [];

const qTypeColour = (t) =>
  t === 'behavioural' ? '#dc2626' :
  t === 'technical'   ? '#1d4ed8' :
  '#d97706';

const qCards = questions.map((q, i) => `
  <div class="q-card">
    <div class="q-header">
      <span class="q-num">${i + 1}</span>
      <span class="q-type" style="background:${qTypeColour(q.question_type)}">${safe(q.question_type)}</span>
    </div>
    <p class="q-text">"${safe(q.question)}"</p>
    <div class="q-rows">
      <div class="q-row"><span class="q-tag">Why they ask it</span><span class="q-val">${safe(q.why_they_ask_it)}</span></div>
      <div class="q-row"><span class="q-tag">Your angle</span><span class="q-val">${safe(q.answer_angle)}</span></div>
      <div class="q-row"><span class="q-tag">Lead with</span><span class="q-val">${safe(q.experience_to_lead_with)}</span></div>
      <div class="q-row"><span class="q-tag">Clifton to deploy</span><span class="q-val">${safe(q.clifton_strength_to_deploy)}</span></div>
      ${q.gap_mitigation ? `<div class="q-row"><span class="q-tag gap-tag">Gap mitigation</span><span class="q-val">${safe(q.gap_mitigation)}</span></div>` : ''}
    </div>
  </div>`).join('');

// ── HTML ───────────────────────────────────────────────────────────────────
